    """SecretStore that resolves secrets from AWS Secrets Manager.

    The configured ``prefix`` is prepended to logical key names before lookup, so
    callers reference secrets by their unprefixed logical name.
    """

    def __init__(self, config: AwsSecretsManagerStoreConfig):
        self.config = config
        self.client = boto3.client("secretsmanager", region_name=config.region)

    def get_secret_values(self, secret_names: List[str]) -> Dict[str, Optional[str]]:
