from typing import Any, Dict, List, Optional

from google.api_core.retry import Retry
from google.cloud import secretmanager
from pydantic import BaseModel

from datahub.secret.secret_store import SecretStore

logger = logging.getLogger(__name__)


class GcpSecretManagerStoreConfig(BaseModel):
    project_id: str
    prefix: str = ""
    cache_ttl: int = 60


class GcpSecretManagerStore(SecretStore):
    """SecretStore that resolves secrets from Google Cloud Secret Manager.

    Resource paths are constructed from the configured ``project_id`` and ``prefix``,
    always resolving the ``latest`` version of each secret.
    """

    def __init__(self, config: GcpSecretManagerStoreConfig):
        self.config = config
        self.client = secretmanager.SecretManagerServiceClient()
        self.retry = Retry()

    def _secret_path(self, secret_name: str) -> str:
        return (
            f"projects/{self.config.project_id}"
            f"/secrets/{self.config.prefix}{secret_name}/versions/latest"
        )

    def get_secret_values(self, secret_names: List[str]) -> Dict[str, Optional[str]]:
        values: Dict[str, Optional[str]] = {}
        for secret_name in secret_names:
            values[secret_name] = self.get_secret_value(secret_name)
        return values

    def get_secret_value(self, secret_name: str) -> Optional[str]:
        name = self._secret_path(secret_name)
        try:
            response = self.client.access_secret_version(
                request={"name": name}, retry=self.retry
            )
            return response.payload.data.decode("UTF-8")
        except Exception:
            # A missing secret (or any lookup failure) resolves to None rather than
            # aborting the resolution of the remaining secrets.
            logger.debug(
                f"Unable to fetch secret '{name}' from GCP Secret Manager.",
                exc_info=True,
            )
            return None

    def get_id(self) -> str:
        return "gcp-sm"

    def close(self) -> None:
        return

    @classmethod
    def create(cls, config: Any) -> "GcpSecretManagerStore":
        config = GcpSecretManagerStoreConfig.model_validate(config)
        return cls(config)
